def stats(g):
    seen=set(); comps=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            q=(y+dy,x+dx)
                            if (dy or dx) and 0<=q[0]<len(g) and 0<=q[1]<len(g[0]) and g[q[0]][q[1]] and q not in seen:
                                seen.add(q); st.append(q)
                comps.append(cells)
    result=[]
    for cells in comps:
        s=set(cells); rs=[r for r,c in s]; cs=[c for r,c in s]
        adj4=sum((r+1,c) in s for r,c in s)+sum((r,c+1) in s for r,c in s)
        adjdiag=sum((r+1,c+1) in s for r,c in s)+sum((r+1,c-1) in s for r,c in s)
        unseen=s.copy(); nc4=0
        while unseen:
            nc4+=1; stack=[unseen.pop()]
            while stack:
                r,c=stack.pop()
                for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if q in unseen: unseen.remove(q); stack.append(q)
        result.append((len(s),(min(rs),min(cs),max(rs),max(cs)),adj4,adjdiag,nc4, sorted((r-min(rs),c-min(cs)) for r,c in s)))
    return result
